    private void AddAeonglassCounters(
        ref StateFingerprintBuilder fingerprint,
        char marker,
        IReadOnlyDictionary<Creature, int>? simulatedValues,
        string memberName)
    {
        ulong first = 0;
        ulong second = 0;
