namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private static int _taskMetricReadObservations;
    private static void TaskMetricReadObserver() => _taskMetricReadObservations++;

    private async Task AssertTaskMetricVariablePresenceAsync(CombatState live, Player player)
    {
        SetStage("task_metric_variable_presence");
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        string[] actualBefore = live.Enemies.Select(e => JsonSerializer.Serialize(CaptureActual(live, player, e))).ToArray();
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        CombatPredictionSimulator parent = root.ForkSimulator();
        string parentBefore = DescribeContinuationContractState(parent, root, player);
        if (!((SimulatedCombatState)parent.State.CombatState).CanReuseMetricVariablePresence)
            throw new InvalidOperationException("Native read permission did not qualify.");

        int contexts = 0, masks = 0, warmMemberships = 0, mutationChecks = 0;
        int[] checks;
        PredictedCard original, grandchild;
        CardModel[] models;
        {
        using IDisposable isolation = SimulationNotificationIsolation.Enter();
        void Compare(IReadOnlyList<PredictedCard> cards, StrategicEffectRequirements requirements, bool exhaust)
        {
            string expected = JsonSerializer.Serialize(TaskOriginalStrategicContext.Build(cards, 351, 23, 4, requirements, exhaust));
            foreach (bool reuse in new[] { false, true, true })
            {
                string actual = JsonSerializer.Serialize(StrategicEffectContext.Build(cards, 351, 23, 4, requirements, exhaust, reuse));
                if (actual != expected) throw new InvalidOperationException("Context differs for " + requirements + "/" + exhaust);
                contexts++;
            }
        }
        void Prime(PredictedCard card)
        {
            StateFingerprint fp = CombatBeamSolver.CaptureCardStateFingerprintForTesting(card);
            card.SetCachedFingerprint(fp.First, fp.Second);
        }
        PredictedCard Shared(CardModel canonical, bool upgrade = false)
        {
            PredictedCard card = PredictedCard.Create(canonical, player);
            if (upgrade && card.Preview.IsUpgradable) card.Upgrade();
            card = card.Fork(new PredictionForkContext());
            Prime(card);
            return card;
        }
        models = [ModelDb.Card<StrikeIronclad>(), ModelDb.Card<BladeDance>(), ModelDb.Card<FanOfKnives>(),
            ModelDb.Card<SwordBoomerang>(), ModelDb.Card<SovereignBlade>(), ModelDb.Card<MadScience>()];
        foreach (bool upgrade in new[] { false, true })
        {
            List<PredictedCard> deck = models.Select(c => Shared(c, upgrade)).ToList();
            foreach (PredictedCard card in deck)
            {
                DynamicVarSet vars = card.Preview.DynamicVars;
                if (!card.TryGetMetricVariablePresence(vars, out byte mask))
                    throw new InvalidOperationException("Shared native card did not cache membership.");
                byte expected = (byte)((vars.TryGetValue("Repeat", out _) ? 1 : 0)
                    | (vars.TryGetValue("Cards", out _) ? 2 : 0) | (vars.TryGetValue("Shivs", out _) ? 4 : 0));
                if (mask != expected) throw new InvalidOperationException("Membership differs for " + card.Preview.Id.Entry);
                masks++;
                card.TryGetMetricVariablePresence(vars, out byte hot);
                if (hot != mask) throw new InvalidOperationException("Warm membership differs.");
                warmMemberships++;
            }
            foreach (StrategicEffectRequirements requirement in new[]
                { StrategicEffectRequirements.None, StrategicEffectRequirements.AttackHits,
                  StrategicEffectRequirements.ShivPlays, (StrategicEffectRequirements)65535 })
                foreach (bool exhaust in new[] { false, true }) Compare(deck, requirement, exhaust);
        }

        original = Shared(ModelDb.Card<StrikeIronclad>());
        if (!original.TryGetMetricVariablePresence(original.Preview.DynamicVars, out byte originalMask) || originalMask != 0)
            throw new InvalidOperationException("Strike fixture has unexpected variables.");
        PredictedCard child = original.Fork(new PredictionForkContext());
        DynamicVarSet writable = child.MutablePreview.DynamicVars;
        DynamicVarSetAccess.RequireVars(writable).Add("Cards", new DynamicVar("Cards", 17));
        if (child.TryGetMetricVariablePresence(writable, out _))
            throw new InvalidOperationException("A mutable preview cached membership.");
        // A retained writable reference can change twice before it becomes shared.
        DynamicVarSetAccess.RequireVars(writable).Add("Repeat", new DynamicVar("Repeat", 3));
        grandchild = child.Fork(new PredictionForkContext());
        Prime(grandchild);
        if (!grandchild.TryGetMetricVariablePresence(grandchild.Preview.DynamicVars, out byte newMask) || newMask != 3
            || !original.TryGetMetricVariablePresence(original.Preview.DynamicVars, out byte preserved) || preserved != 0)
            throw new InvalidOperationException("COW membership or parent isolation failed.");
        if (original.TryGetMetricVariablePresence(grandchild.Preview.DynamicVars, out _))
            throw new InvalidOperationException("A foreign variable set reused another preview certificate.");
        original.InvalidateCaches();
        if (original.TryGetMetricVariablePresence(original.Preview.DynamicVars, out _))
            throw new InvalidOperationException("Explicit invalidation retained a warm certificate.");
        Prime(original);
        if (!original.TryGetMetricVariablePresence(original.Preview.DynamicVars, out byte restoredMask) || restoredMask != 0)
            throw new InvalidOperationException("Rebuilt certificate differs after invalidation.");
        mutationChecks += 7;
        Compare([original, child, grandchild], (StrategicEffectRequirements)65535, false);
        child.MutablePreview.DynamicVars["Cards"].BaseValue = 29;
        Compare([child], StrategicEffectRequirements.AttackHits, false);
        if (grandchild.Preview.DynamicVars["Cards"].BaseValue != 17)
            throw new InvalidOperationException("A numeric write leaked into a sibling.");
        PredictedCard cloned = grandchild.Clone();
        if (cloned.TryGetMetricVariablePresence(cloned.Preview.DynamicVars, out _))
            throw new InvalidOperationException("Clone inherited shared eligibility.");
        cloned.EnableAttachedModelForkIsolation();
        PredictedCard opaque = cloned.Fork(new PredictionForkContext());
        if (opaque.TryGetMetricVariablePresence(opaque.Preview.DynamicVars, out _))
            throw new InvalidOperationException("Opaque preview cached membership.");
        mutationChecks += 3;

        PredictedCard overflow = Shared(ModelDb.Card<StrikeIronclad>());
        DynamicVarSetAccess.RequireVars(overflow.MutablePreview.DynamicVars).Add("Cards", new DynamicVar("Cards", -3000000000m));
        overflow = overflow.Fork(new PredictionForkContext());
        Prime(overflow);
        bool OriginalThrows() { try { TaskOriginalStrategicContext.Build([overflow], 351, 23, 4, StrategicEffectRequirements.AttackHits); return false; } catch (OverflowException) { return true; } }
        bool CandidateThrows() { try { StrategicEffectContext.Build([overflow], 351, 23, 4, StrategicEffectRequirements.AttackHits, false, true); return false; } catch (OverflowException) { return true; } }
        if (!OriginalThrows() || !CandidateThrows()) throw new InvalidOperationException("Present-value conversion exception changed.");

        CombatPredictionSimulator[] siblings = Enumerable.Range(0, 16).Select(_ => parent.Fork()).ToArray();
        PredictedCard[] cardSiblings = Enumerable.Range(0, 16).Select(_ => original.Fork(new PredictionForkContext())).ToArray();
        checks = await Task.WhenAll(siblings.Select((sim, index) => Task.Run(() =>
        {
            using IDisposable workerIsolation = SimulationNotificationIsolation.Enter();
            string before = DescribeContinuationContractState(sim, root, player);
            PredictedCard card = cardSiblings[index];
            if (!card.TryGetMetricVariablePresence(card.Preview.DynamicVars, out byte mask) || mask != 0)
                throw new InvalidOperationException("Parallel shared membership failed.");
            PredictedCard next = card.Fork(new PredictionForkContext());
            if (!next.TryGetMetricVariablePresence(next.Preview.DynamicVars, out byte nextMask) || nextMask != 0
                || before != DescribeContinuationContractState(sim.Fork(), root, player)
                || before != DescribeContinuationContractState(sim, root, player))
                throw new InvalidOperationException("Parallel state/Fork/RNG isolation failed.");
            return 1;
        })));
        }
        MethodInfo[] guarded =
        [typeof(CardModel).GetProperty(nameof(CardModel.DynamicVars))!.GetMethod!,
         typeof(DynamicVarSet).GetMethod(nameof(DynamicVarSet.TryGetValue), [typeof(string), typeof(DynamicVar).MakeByRefType()])!];
        MethodInfo observer = typeof(UnattendedTestRunner).GetMethod(nameof(TaskMetricReadObserver), BindingFlags.Static | BindingFlags.NonPublic)!;
        Harmony harmony = new("CombatSolver.Tests.TaskMetricVariablePresence");
        int unknownRefusals = 0;
        foreach (MethodInfo method in guarded)
        {
            try
            {
                harmony.Patch(method, prefix: new HarmonyMethod(observer));
                if (PredictionDynamicVarReadAudit.Capture()) throw new InvalidOperationException("Unknown getter/lookup patch qualified.");
                CombatRootSnapshot rejectedRoot = CombatRootSnapshot.Capture(live);
                bool permission = ((SimulatedCombatState)rejectedRoot.ForkSimulator().State.CombatState).CanReuseMetricVariablePresence;
                if (permission || !((SimulatedCombatState)parent.Fork().State.CombatState).CanReuseMetricVariablePresence)
                    throw new InvalidOperationException("Root permission was not frozen independently.");
                using IDisposable fallbackIsolation = SimulationNotificationIsolation.Enter();
                _taskMetricReadObservations = 0;
                string expected = JsonSerializer.Serialize(TaskOriginalStrategicContext.Build([original, grandchild], 351, 23, 4, StrategicEffectRequirements.AttackHits));
                int expectedReads = _taskMetricReadObservations;
                _taskMetricReadObservations = 0;
                string actual = JsonSerializer.Serialize(StrategicEffectContext.Build([original, grandchild], 351, 23, 4, StrategicEffectRequirements.AttackHits, false, permission));
                if (expected != actual || expectedReads == 0 || expectedReads != _taskMetricReadObservations)
                    throw new InvalidOperationException("Unknown patch fallback changed values or observations.");
                unknownRefusals++;
            }
            finally { harmony.Unpatch(method, observer); }
        }
        if (liveBefore != ContinuationStamp.CaptureLive(live).StateText
            || parentBefore != DescribeContinuationContractState(parent, root, player)
            || !actualBefore.SequenceEqual(live.Enemies.Select(e => JsonSerializer.Serialize(CaptureActual(live, player, e)))))
            throw new InvalidOperationException("Native/parent/live/RNG state changed.");
        _completedChecks.Add("TaskMetricVariablePresence:" + JsonSerializer.Serialize(new
            { nativeTypes = models.Length, contexts, masks, warmMemberships, mutationChecks,
              parallelSiblings = checks.Sum(), unknownRefusals, presentConversionExceptionPreserved = true,
              fullNativeAndParentAndLiveAndRngUnchanged = true }));
    }
}

