        }
        if (liveBefore != ContinuationStamp.CaptureLive(live).StateText
            || parentBefore != DescribeContinuationContractState(parent, root, player)
            || !actualBefore.SequenceEqual(live.Enemies.Select(e => JsonSerializer.Serialize(CaptureActual(live, player, e)))))
            throw new InvalidOperationException("Native/parent/live/RNG state changed.");
        _completedChecks.Add("TaskMetricVariablePresence:" + JsonSerializer.Serialize(new
            { nativeTypes = models.Length, contexts, masks, warmMemberships, mutationChecks,
              parallelSiblings = checks.Sum(), unknownRefusals, presentConversionExceptionPreserved = true,
              fullNativeAndParentAndLiveAndRngUnchanged = true }));
    }
}

