using System.Reflection;
using HarmonyLib;
using MegaCrit.Sts2.Core.Localization.DynamicVars;
using MegaCrit.Sts2.Core.Models;

namespace CombatSolver;

// Root-frozen permission for reusing dictionary membership in immutable card
// previews. Numeric values/conversions are never elided. Worker lanes inspect
// only their COW card state, never the live Harmony registry.
internal static class PredictionDynamicVarReadAudit
{
    private static readonly Guid AuditedModule = new("8a76776c-0ce1-4d4f-90bd-8cce653dad8e");
    private static readonly MethodInfo[] Reads =
    [
        typeof(CardModel).GetProperty(nameof(CardModel.DynamicVars))!.GetMethod!,
        typeof(DynamicVarSet).GetMethod(nameof(DynamicVarSet.TryGetValue),
            [typeof(string), typeof(DynamicVar).MakeByRefType()])!,
    ];

    internal static bool Capture()
        => Reads.All(method => method.Module.ModuleVersionId == AuditedModule
            && (!method.IsVirtual || method.IsFinal)
            && Harmony.GetPatchInfo(method) is not { Owners.Count: > 0 });
}

